  matrix[N, J] data_matrix[Q];
  // district-season indicators: Q quarters of a Nx(D-1) matrix
  matrix[N, D-1] district_season[Q];
}

transformed data {
  vector[N] traum_injuries_vec[Q];

  for (i in 1:N)

    for (q in 1:Q)

      traum_injuries_vec[q,i] <- traum_injuries[q,i];
